using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int ChargedFor(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    [Fact]
    public void S1_BronzeCustomerIsChargedBronzePrice() // Bronze customer is charged the Bronze price
    {
        Assert.Equal(9500, ChargedFor(10000, LoyaltyTier.Bronze));
    }

    [Fact]
    public void S2_SilverCustomerIsChargedSilverPrice() // Silver customer is charged the Silver price
    {
        Assert.Equal(9000, ChargedFor(10000, LoyaltyTier.Silver));
    }

    [Fact]
    public void S3_GoldCustomerIsChargedGoldPrice() // Gold customer is charged the Gold price
    {
        Assert.Equal(8500, ChargedFor(10000, LoyaltyTier.Gold));
    }

    [Fact]
    public void S4_BronzeTinyBasketIsChargedWholeCentInTheirFavour() // Bronze customer with a tiny basket is charged a whole cent in their favour
    {
        Assert.Equal(7, ChargedFor(7, LoyaltyTier.Bronze));
    }
}

